//! Privacy rules: which clipboard changes must never be recorded.

/// Pasteboard types set by password managers and other apps to mark data that
/// must not be stored (see nspasteboard.org).
pub const CONCEALED_TYPES: [&str; 2] = [
    "org.nspasteboard.ConcealedType",
    "com.agilebits.onepassword",
];

pub const TRANSIENT_TYPES: [&str; 3] = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "de.petermaurer.TransientPasteboardType",
];

pub const SENSITIVE_TYPES: [&str; 5] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
];

/// Bundle ids ignored out of the box.
pub fn default_ignored_apps() -> Vec<String> {
    [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.agilebits.onepassword-osx",
        "com.bitwarden.desktop",
        "org.keepassxc.keepassxc",
        "com.lastpass.LastPass",
        "com.apple.keychainaccess",
        "com.dashlane.dashlanephonefinal",
    ]
    .into_iter()
    .map(String::from)
    .collect()
}

/// Returns true if this pasteboard snapshot must be skipped.
pub fn should_ignore<S: AsRef<str>>(
    types: &[S],
    source_bundle: &str,
    ignored_apps: &[String],
) -> bool {
    should_ignore_with_options(types, source_bundle, ignored_apps, true, true)
}

pub fn should_ignore_with_options<S: AsRef<str>>(
    types: &[S],
    source_bundle: &str,
    ignored_apps: &[String],
    ignore_sensitive: bool,
    ignore_transient: bool,
) -> bool {
    if types.iter().any(|t| {
        (ignore_sensitive && CONCEALED_TYPES.contains(&t.as_ref()))
            || (ignore_transient && TRANSIENT_TYPES.contains(&t.as_ref()))
    }) {
        return true;
    }
    ignored_apps
        .iter()
        .any(|b| !b.is_empty() && b.eq_ignore_ascii_case(source_bundle))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn concealed_ignored() {
        let types = ["public.utf8-plain-text", "org.nspasteboard.ConcealedType"];
        assert!(should_ignore(&types, "com.apple.Safari", &[]));
    }

    #[test]
    fn blacklisted_app() {
        let ignored = default_ignored_apps();
        assert!(should_ignore(
            &["public.utf8-plain-text"],
            "com.BitWarden.desktop",
            &ignored
        ));
        assert!(!should_ignore(
            &["public.utf8-plain-text"],
            "com.apple.Safari",
            &ignored
        ));
        assert!(!should_ignore(&["public.utf8-plain-text"], "", &ignored));
    }
}
